/** Read the original attachment without reformatting: report lines refer to it. */
export async function embeddedInvoiceXml(data: ArrayBuffer): Promise<string> {
  const { getDocument, GlobalWorkerOptions } =
    await import('pdfjs-dist/legacy/build/pdf.mjs');
  const { default: workerUrl } =
    await import('pdfjs-dist/legacy/build/pdf.worker.min.mjs?url');
  GlobalWorkerOptions.workerSrc = workerUrl;
  const task = getDocument({ data, isEvalSupported: false });
  try {
    const pdf = await task.promise;
    const attachments = Object.values(
      ((await pdf.getAttachments()) || {}) as Record<
        string,
        { filename: string; content: Uint8Array }
      >,
    );
    const attachment =
      attachments.find((a) =>
        /^(factur-x|zugferd-invoice|xrechnung)\.xml$/i.test(a.filename),
      ) || attachments.find((a) => /\.xml$/i.test(a.filename));
    if (!attachment) throw new Error('einvoice_xml_not_available');
    return new TextDecoder('utf-8').decode(attachment.content);
  } finally {
    await task.destroy();
  }
}
